"""Generate the synthetic flat-chord pattern set and its special-shape mesh.

TEST DATA TOOL. Everything here is made up from an analytic shape; it is not a real or
licensed design and passing the tests that use it says nothing about airworthiness.

* ``shape.yaml``: the generated block is the tape profile through 11 row corners on the
  curve :math:`r = R\\cos\\theta\\,(1 + \\epsilon \\sin\\theta)`,
  :math:`z = c R \\sin\\theta` (a slightly pear-shaped, slightly tall sphere), straight
  between corners, with 10 rows; the "measured" seam bows are those of a crest loft of
  :data:`MEASURED_FRACTION` (not the file's own ``loft.crest``) with the two sides of every
  seam made to differ by :data:`ASYMMETRY`, as in hand-drawn patterns.
* ``shapes/blister.obj``: a closed mesh blister for the ``mesh`` shape of
  ``special.yaml``: an elliptical footprint round its base point, standing
  :data:`BLISTER_HEIGHT` proud, sunk :data:`BLISTER_DEPTH` into the envelope.

Usage::

    python tests/fixtures/flat_chord_pattern/make_fixture.py           # write the files
    python tests/fixtures/flat_chord_pattern/make_fixture.py --check   # exit 1 if stale
"""

from __future__ import annotations

import argparse
import math
import sys
from dataclasses import replace
from pathlib import Path

import numpy as np
from scipy.spatial import Delaunay

from envelopelab.features.primitives import EnvelopeSurface
from envelopelab.geometry.gore import CrestLoft, MeridianProfile, crest_bows
from envelopelab.io.shape_file import load_shape_file

HERE = Path(__file__).resolve().parent
SHAPE = HERE / "shape.yaml"
SPECIAL = HERE / "special.yaml"
MESH = HERE / "shapes" / "blister.obj"
BEGIN = "# --- BEGIN GENERATED by make_fixture.py (do not edit by hand) ---"
END = "# --- END GENERATED ---"
#: Shape: radius (m), pear and height factors, corner latitudes (deg), row names.
RADIUS = 8.5
PEAR = 0.08
TALL = 1.05
LATITUDES = np.linspace(-72.0, 70.0, 11)
ROWS = ("SKIRT", "A", "B", "C", "D", "E", "F", "G", "H", "I")
#: "Measured" bows: a crest loft other than the file's own, plus a seam asymmetry, m.
MEASURED_FRACTION = 0.025
MEASURED_TAPER = ((0.1, 0.5, 1.0), (0.0, 1.0, 0.0))
ASYMMETRY = 0.0008
#: Blister of the mesh shape: semi-axes across and up (m), height (m), depth (m).
BLISTER_AXES = (0.9, 0.7)
BLISTER_HEIGHT = 0.5
BLISTER_DEPTH = 0.3
BLISTER_SPACING = 0.08
BLISTER_RIM = 96
BLISTER_OVERSHOOT = 1.08


def corners() -> tuple[np.ndarray, np.ndarray]:
    """Row-corner radii and heights, m, mouth first."""
    theta = np.radians(LATITUDES)
    return RADIUS * np.cos(theta) * (1.0 + PEAR * np.sin(theta)), TALL * RADIUS * np.sin(theta)


def measured_bows() -> list[tuple[float, float]]:
    """(bottom, top) bow of every row, m."""
    r, z = corners()
    profile = MeridianProfile.from_control_points(r, z, interpolation="linear")
    bounds = np.concatenate(([0.0], np.cumsum(np.hypot(np.diff(r), np.diff(z)))))
    crest = CrestLoft(MEASURED_FRACTION, *MEASURED_TAPER)
    bows = [list(p) for p in crest_bows(profile, bounds, crest)]
    for k in range(len(bows) - 1):  # the two sides of seam k / k+1 differ a little
        sign = 1.0 if k % 2 == 0 else -1.0
        bows[k][1] += sign * ASYMMETRY
        bows[k + 1][0] -= sign * ASYMMETRY
    return [(float(a), float(b)) for a, b in bows]


def generated_block() -> str:
    r, z = corners()
    chords = np.hypot(np.diff(r), np.diff(z))
    total = float(chords.sum())
    s = np.concatenate(([0.0], np.cumsum(chords))) / total
    s[-1] = 1.0
    lines = [
        BEGIN,
        "profile:",
        "  source: assumed            # synthetic (see README.md)",
        "  span: cut                  # s = 0 at the mouth, s = 1 at the top opening",
        "  interpolation: linear      # straight load tape between row corners",
        "  stations:                  # [s, r], fractions of the tape length T",
    ]
    lines += [f"    - [{a:.8f}, {b:.8f}]" for a, b in zip(s, r / total, strict=True)]
    lines += ["", "rows:                        # mouth first; bows in mm, positive outward"]
    for k, (name, (low, high)) in enumerate(zip(ROWS, measured_bows(), strict=True)):
        zone = "mouth" if k == 0 else "body"
        top = "" if k == len(ROWS) - 1 else f" top: {s[k + 1]:.8f},"
        bow = f"[{low * 1e3:.2f} mm, {high * 1e3:.2f} mm]"
        lines.append(f"  - {{name: {name},{top} zone: {zone}, bow: {bow}}}")
    lines += ["", "design:", "  construction: flat_chord", "  hold:"]
    lines += [f"    tape_length: {total * 1e3:.2f} mm", END]
    return "\n".join(lines) + "\n"


def blister_mesh() -> tuple[np.ndarray, np.ndarray]:
    """Closed blister mesh in the shape frame (z out, x up the tape), m."""
    special = load_shape_file(SPECIAL)
    design = special.design()
    surface = EnvelopeSurface.from_design(design)
    # Resolve the blister's placement without reading the mesh this script writes.
    (entry,) = [e for e in special.special_shapes if e["name"] == "blister"]
    stand_in = {"name": "blister", "kind": "dome", "placement": entry["placement"]}
    stand_in |= {"base_radius": "1 m", "height": "1 m"}
    (spec,) = replace(special, special_shapes=(stand_in,)).shapes(design)
    s0 = spec.placement.tape_position
    g0 = spec.placement.gore - 0.5 + spec.placement.across
    k = surface.gore_angle * float(np.interp(s0, surface.profile.s, surface.profile.r))
    a, b = BLISTER_AXES
    t = np.linspace(0.0, 2.0 * math.pi, BLISTER_RIM, endpoint=False)
    outer = BLISTER_OVERSHOOT * np.column_stack([a * np.cos(t), b * np.sin(t)])
    gu, gv = np.meshgrid(
        np.arange(-a, a, BLISTER_SPACING) + 0.5 * BLISTER_SPACING,
        np.arange(-b, b, BLISTER_SPACING) + 0.5 * BLISTER_SPACING,
    )
    grid = np.column_stack([gu.ravel(), gv.ravel()])
    rho = np.hypot(grid[:, 0] / a, grid[:, 1] / b)
    grid = grid[(rho < BLISTER_OVERSHOOT - 0.05) & (rho > 0.05)]
    uv = np.vstack([[0.0, 0.0], grid, outer])
    first_outer = len(uv) - len(outer)
    tri = Delaunay(uv).simplices
    p, q, w = uv[tri[:, 0]], uv[tri[:, 1]], uv[tri[:, 2]]
    ccw = (q[:, 0] - p[:, 0]) * (w[:, 1] - p[:, 1]) - (q[:, 1] - p[:, 1]) * (w[:, 0] - p[:, 0])
    tri = np.where((ccw > 0)[:, None], tri, tri[:, ::-1])
    rho = np.minimum(np.hypot(uv[:, 0] / a, uv[:, 1] / b), BLISTER_OVERSHOOT)
    s = s0 + uv[:, 1]
    theta = (g0 + uv[:, 0] / k) * surface.gore_angle
    on = surface.point(s, theta)
    normals = np.array([surface.frame(x, y)[2] for x, y in zip(s, theta, strict=True)])
    top = on + (BLISTER_HEIGHT * (1.0 - rho**2))[:, None] * normals
    bottom = on - BLISTER_DEPTH * normals
    _, e_up, normal = surface.frame(float(s[0]), float(theta[0]))
    b1, b2, base = e_up, np.cross(normal, e_up), on[0]

    def local(pts: np.ndarray) -> np.ndarray:
        rel = pts - base
        return np.column_stack([rel @ b1, rel @ b2, rel @ normal])

    n = len(uv)
    ring = np.arange(first_outer, n)
    nxt = np.roll(ring, -1)
    faces = np.vstack(
        [
            tri,
            tri[:, ::-1] + n,
            np.column_stack([ring, ring + n, nxt + n]),
            np.column_stack([ring, nxt + n, nxt]),
        ]
    )
    return np.vstack([local(top), local(bottom)]), faces.astype(np.int64)


def obj_text(verts: np.ndarray, faces: np.ndarray) -> str:
    lines = [
        "# Synthetic blister (generated by make_fixture.py; do not edit by hand)",
        "# Shape frame, m: z out of the envelope, x up the tape, origin at the base point.",
    ]
    lines += [f"v {x:.6f} {y:.6f} {z:.6f}" for x, y, z in verts]
    lines += [f"f {i + 1} {j + 1} {k + 1}" for i, j, k in faces]
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if the files are stale")
    args = parser.parse_args(argv)
    text = SHAPE.read_text(encoding="utf-8")
    start, stop = text.index(BEGIN), text.index(END) + len(END) + 1
    shape_text = text[:start] + generated_block() + text[stop:]
    stale = []
    if args.check:
        if shape_text != text:
            stale.append(SHAPE.name)
    else:
        SHAPE.write_text(shape_text, encoding="utf-8")
    mesh_text = obj_text(*blister_mesh())
    if args.check:
        if not MESH.is_file() or MESH.read_text(encoding="utf-8") != mesh_text:
            stale.append(MESH.name)
    else:
        MESH.parent.mkdir(exist_ok=True)
        MESH.write_text(mesh_text, encoding="utf-8")
    if stale:
        print(
            "stale: " + ", ".join(stale) + "; run tests/fixtures/flat_chord_pattern/make_fixture.py"
        )
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
